import { field, select, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "ttWidth", label: "Element width (px)", type: "number", help: "Width of the interactive element in CSS pixels.", value: "40" })}${field({ id: "ttHeight", label: "Element height (px)", type: "number", help: "Height of the interactive element in CSS pixels.", value: "40" })}</div><div class="field-grid">${field({ id: "ttSpacing", label: "Spacing to nearest element (px)", type: "number", help: "Distance to the nearest adjacent interactive element. 0 if unknown.", value: "0" })}${select({ id: "ttType", label: "Element type", options: [{label:"Generic (button, link, input)",value:"generic"},{label:"Inline link (in text)",value:"inline"},{label:"User-agent control (native)",value:"ua"},{label:"Essential (no alternative layout)",value:"essential"}], value: "generic" })}</div>`,generate(root) {const width = parseFloat(root.querySelector("#ttWidth").value) || 0;const height = parseFloat(root.querySelector("#ttHeight").value) || 0;const spacing = parseFloat(root.querySelector("#ttSpacing").value) || 0;const type = root.querySelector("#ttType").value;const targetSize = Math.min(width, height);const lines = [];lines.push("=== WCAG 2.2 Target Size (2.5.8) Check ===");lines.push(`Element: ${width}x${height}px | Spacing: ${spacing}px | Type: ${type}`);lines.push("");let meetsAA = targetSize >= 24;let meetsAAA = targetSize >= 44;let exceptionApplied = false;let exceptionReason = "";if (type === "inline" && !meetsAA) {meetsAA = true;exceptionApplied = true;exceptionReason = "Inline exception: links within text blocks are exempt from minimum target size.";}if (type === "ua" && !meetsAA) {meetsAA = true;exceptionApplied = true;exceptionReason = "User-agent exception: native browser controls are rendered by the platform.";}if (type === "essential" && !meetsAA) {meetsAA = true;exceptionApplied = true;exceptionReason = "Essential exception: the element cannot be presented differently without changing the functionality.";}if (!meetsAA && spacing >= 24 && targetSize >= 20) {meetsAA = true;exceptionApplied = true;exceptionReason = `Spacing exception: the element has ${spacing}px spacing (>= 24px) and is at least 20px. Another target within 24px of this target also meets its own size requirement.`;}lines.push(`AA (24px minimum): ${meetsAA ? "PASS" : "FAIL"}`);lines.push(`AAA (44px minimum): ${meetsAAA ? "PASS" : "FAIL"}`);lines.push("");if (exceptionApplied) {lines.push(`Exception applied: ${exceptionReason}`);lines.push("");}if (!meetsAA) {const needW = Math.max(0, 24 - width);const needH = Math.max(0, 24 - height);const fixW = needW > 0 ? ` or increase width by ${needW}px` : "";const fixH = needH > 0 ? ` or increase height by ${needH}px` : "";lines.push(`Fix: Increase element size to at least 24x24px${fixW}${fixH}, or ensure spacing to adjacent elements is at least 24px.`);lines.push("");lines.push("/* CSS fix: */");if (needW > 0) lines.push(`/* min-width: 24px; */`);if (needH > 0) lines.push(`/* min-height: 24px; */`);lines.push("/* padding or gap for spacing to adjacent targets */");}if (!meetsAAA) {lines.push("");lines.push("For AAA: increase to at least 44x44px (CSS min-width/min-height: 44px).");}if (meetsAA && meetsAAA) {lines.push("The element meets both AA and AAA target size requirements. No changes needed.");}lines.push("");lines.push("/* WCAG 2.5.8 Exceptions: */","/* Inline: Links in text blocks. */","/* User-agent: Native browser controls (checkbox, radio). */","/* Essential: No alternative presentation possible. */","/* Spacing: >= 24px between adjacent targets. */","/* Equivalent: Another control on the page does the same thing. */");return { output: lines.join("\n") };}};